docker exec -it cass cqlsh    (po ok. minucie startu)
CREATE KEYSPACE sklep WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};
USE sklep;
CREATE TABLE zamowienia_klienta (klient_id int, data_zamowienia timestamp, zamowienie_id int, kwota decimal,
  PRIMARY KEY (klient_id, data_zamowienia)) WITH CLUSTERING ORDER BY (data_zamowienia DESC);
INSERT INTO zamowienia_klienta (klient_id, data_zamowienia, zamowienie_id, kwota) VALUES (42, '2026-09-26 10:00:00+0000', 1, 100.00);
INSERT INTO zamowienia_klienta (klient_id, data_zamowienia, zamowienie_id, kwota) VALUES (42, '2026-09-26 10:00:00+0000', 2, 250.00);
SELECT zamowienie_id, kwota FROM zamowienia_klienta WHERE klient_id = 42;
-> tylko zamówienie 2 (250.00) - zamówienie 1 zostało po cichu NADPISANE (sprawdzone na Cassandrze 5).
INSERT z istniejącym kluczem głównym to upsert, bez błędu. Poprawka: PRIMARY KEY ((klient_id), data_zamowienia, zamowienie_id) WITH CLUSTERING ORDER BY (data_zamowienia DESC, zamowienie_id ASC) - klucz jednoznacznie identyfikuje zamówienie; po tej zmianie count(*) dla klienta 42 zwraca 2. Keyspace z SimpleStrategy i RF=1 nadaje się tylko do nauki; produkcyjnie NetworkTopologyStrategy i RF=3.

CREATE TABLE odczyty_czujnika (
  czujnik_id text, dzien date, czas timestamp, wartosc double,
  PRIMARY KEY ((czujnik_id, dzien), czas)
) WITH CLUSTERING ORDER BY (czas DESC)
  AND default_time_to_live = 7776000;   -- 90 dni
(1) SELECT * FROM odczyty_czujnika WHERE czujnik_id = 'T-17' AND dzien = '2026-09-26' LIMIT 100; (przy przejściu przez północ - dodatkowo poprzedni dzień)
(2) SELECT * FROM odczyty_czujnika WHERE czujnik_id = 'T-17' AND dzien = '2026-09-26';
CREATE TABLE czujniki_w_budynku (budynek_id text, czujnik_id text, typ text, PRIMARY KEY (budynek_id, czujnik_id));
(3) SELECT * FROM czujniki_w_budynku WHERE budynek_id = 'B1';
Bucketing: gdyby kluczem partycji był sam czujnik_id, partycja rosłaby bez końca (miliony odczytów na jednym węźle - 'gorąca', ogromna partycja). Dodanie dnia do klucza partycji dzieli dane czujnika na dzienne porcje o przewidywalnym rozmiarze. TTL tabeli automatycznie usuwa stare odczyty. Dane czujnika (typ, budynek) są świadomie powielane w kilku tabelach.

